  add({"id":"fed-hr-2385","level":"federal","bill":"H.R. 2385","title":"CREATE AI Act of 2025","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/2385/text"},"status":"Introduced March 26, 2025. Committee: Science, Space, and Technology","summary":"Would set up a national AI research resource that gives universities, nonprofits and small businesses computing power for AI experiments and testing.","topics":["Voluntary standards"],"lastAction":{"date":"2026-06-25","text":"Ordered to be Reported in the Nature of a Substitute (Amended) by the Yeas and Nays: 29 - 0."}});
  add({"id":"fed-s-1269","level":"federal","bill":"S. 1269","title":"Promoting United States Leadership in Standards Act of 2025","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/senate-bill/1269/text"},"status":"Introduced April 2, 2025. Committee: Health, Education, Labor, and Pensions; Commerce, Science, and Transportation","summary":"Would have NIST support technical standard-setting work on AI.","topics":["Voluntary standards"],"lastAction":{"date":"2026-03-19","text":"Committee on Health, Education, Labor, and Pensions. Hearings held."}});
  add({"id":"fed-s-1633","level":"federal","bill":"S. 1633","title":"TEST AI Act of 2025","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/senate-bill/1633/text"},"status":"Introduced May 7, 2025. Committee: Commerce, Science, and Transportation","summary":"Would have NIST and the Energy Department explore measurement standards for evaluating AI systems and set up testbeds for them.","topics":["Voluntary standards"],"lastAction":{"date":"2025-05-07","text":"Read twice and referred to the Committee on Commerce, Science, and Transportation."}});
  add({"id":"fed-s-2615","level":"federal","bill":"S. 2615","title":"VET Artificial Intelligence Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/senate-bill/2615/text"},"status":"Introduced July 31, 2025. Committee: Commerce, Science, and Transportation","summary":"Would have NIST create voluntary standards for internal and outside evaluations of AI systems, plus guidance on disclosing results and corrective steps.","topics":["Socioeconomic harms","Voluntary standards","Third-party audits"],"lastAction":{"date":"2025-07-31","text":"Read twice and referred to the Committee on Commerce, Science, and Transportation."}});
  add({"id":"fed-s-2750","level":"federal","bill":"S. 2750","title":"SANDBOX Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/senate-bill/2750/text"},"status":"Introduced September 10, 2025. Committee: Commerce, Science, and Transportation","summary":"Would let people testing or deploying AI apply for waivers from federal rules; agencies decide, and the White House science office can overrule them.","topics":["Catastrophic risk","Socioeconomic harms","Deregulation"],"lastAction":{"date":"2025-09-10","text":"Read twice and referred to the Committee on Commerce, Science, and Transportation."}});
  add({"id":"fed-hr-5388","level":"federal","bill":"H.R. 5388","title":"American Artificial Intelligence Leadership and Uniformity Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/5388/text"},"status":"Introduced September 16, 2025. Committee: Veterans' Affairs; Homeland Security; Transportation and Infrastructure and 9 more","summary":"Would order a national AI action plan and bar state and local governments from enforcing rules on AI models for five years.","topics":["Transparency","Preemption","Deregulation"],"lastAction":{"date":"2025-12-19","text":"Referred to the Subcommittee on Oversight and Investigations."}});
  add({"id":"fed-s-2938","level":"federal","bill":"S. 2938","title":"Artificial Intelligence Risk Evaluation Act of 2025","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/senate-bill/2938/text"},"status":"Introduced September 29, 2025. Committee: Homeland Security and Governmental Affairs; Commerce, Science, and Transportation","summary":"Would require advanced AI developers to take part in a federal program that tests their models and recommends fixes to the developer and Congress.","topics":["Catastrophic risk","Socioeconomic harms","Mandatory testing"],"lastAction":{"date":"2026-09-30","text":"Committee on Homeland Security and Governmental Affairs. Hearings held."}});
  add({"id":"fed-s-2937","level":"federal","bill":"S. 2937","title":"AI LEAD Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/senate-bill/2937/text"},"status":"Introduced September 29, 2025. Committee: Judiciary","summary":"Would make AI developers and deployers liable for harms from their products, overriding conflicting state laws but keeping stronger state protections.","topics":["Socioeconomic harms","Liability","Anti-preemption"],"lastAction":{"date":"2025-09-29","text":"Read twice and referred to the Committee on the Judiciary. (text: CR S6836-6838)"}});
  add({"id":"fed-s-3202","level":"federal","bill":"S. 3202","title":"Advanced Artificial Intelligence Security Readiness Act of 2025","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/senate-bill/3202/text"},"status":"Introduced November 19, 2025. Committee: Intelligence (Select)","summary":"Would have the NSA issue guidance on spotting and guarding against AI supply chain risks.","topics":["Catastrophic risk","Voluntary standards"],"lastAction":{"date":"2025-11-19","text":"Read twice and referred to the Select Committee on Intelligence."}});
  add({"id":"fed-s-3557","level":"federal","bill":"S. 3557","title":"States' Right to Regulate AI Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/senate-bill/3557/text"},"status":"Introduced December 17, 2025. Committee: Commerce, Science, and Transportation","summary":"Would bar federal money from being used to carry out Executive Order 14365, which targets funding for states whose AI laws conflict with administration policy.","topics":["Anti-preemption"],"lastAction":{"date":"2025-12-17","text":"Read twice and referred to the Committee on Commerce, Science, and Transportation."}});
  add({"id":"fed-s-3592","level":"federal","bill":"S. 3592","title":"PROTECT Military Families Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/senate-bill/3952/text"},"status":"Introduced January 7, 2026. Committee: Judiciary","summary":"Would put the Center for AI Standards and Innovation into law to develop voluntary model-assessment standards, and add AI prizes and open public data for training and evaluation.","topics":["Catastrophic risk","Voluntary standards"],"lastAction":{"date":"2026-01-07","text":"Read twice and referred to the Committee on the Judiciary."}});
  add({"id":"fed-hr-8031","level":"federal","bill":"H.R. 8031; S. 4216","title":"GUARDRAILS Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/8031/text"},"status":"Introduced in the House March 20, 2026 and in the Senate March 26, 2026. Committees: House: Judiciary; Energy and Commerce. Senate: Commerce, Science, and Transportation","summary":"Would repeal Executive Order 14365 and bar federal money for carrying it out; the order targets funding for states whose AI laws conflict with administration policy.","topics":["Anti-preemption"],"lastAction":{"date":"2026-03-26","text":"Read twice and referred to the Committee on Commerce, Science, and Transportation."}});
  add({"id":"fed-hr-8094","level":"federal","bill":"H.R. 8094","title":"AI Foundation Model Transparency Act of 2026","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/8094/text"},"status":"Introduced March 26, 2026. Committee: Energy and Commerce","summary":"Would require public disclosure of foundation-model details, including information about training data.","topics":["Catastrophic risk","Socioeconomic harms","Transparency"],"lastAction":{"date":"2026-03-26","text":"Referred to the House Committee on Energy and Commerce."}});
  add({"id":"fed-hr-8516","level":"federal","bill":"H.R. 8516","title":"American Leadership in AI Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/8516/text"},"status":"Introduced April 27, 2026. Committee: Ways and Means; Judiciary; Education and Workforce and 4 more","summary":"Would have NIST pursue international AI standards, voluntary guidance and incident reporting, and set minimum requirements for federal AI purchases; also codifies the standards center and the national research resource, and adds R&D prizes.","topics":["Catastrophic risk","Government AI risks","Voluntary standards","Transparency"],"lastAction":{"date":"2026-04-27","text":"Referred to the Committee on Science, Space, and Technology, and in addition to the Committees on Energy and Commerce, Agriculture, Oversight and Government Reform, Education and Workforce, the Judiciary, and Ways and Means, for a period to be subsequently determined by the Speaker, in each case for consideration of such provisions as fall within the jurisdiction of the committee concerned."}});
  add({"id":"fed-hr-9323","level":"federal","bill":"H.R. 9323","title":"Department of Advanced Technology and Artificial Intelligence Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/9323/text"},"status":"Introduced June 15, 2026. Committee: Oversight and Government Reform","summary":"Would create a new department to set safety and oversight standards for federal AI use and run incident reporting for cybersecurity risks.","topics":["Socioeconomic harms","Government AI risks","Voluntary standards","Transparency"],"lastAction":{"date":"2026-06-15","text":"Referred to the House Committee on Oversight and Government Reform."}});
  add({"id":"fed-hr-9363","level":"federal","bill":"H.R. 9363","title":"AI Security and Innovation Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/9363/text"},"status":"Introduced June 18, 2026. Committee: Science, Space, and Technology","summary":"Would write the AI standards center into law as part of NIST for now and have it make voluntary risk-evaluation agreements with developers.","topics":["Catastrophic risk","Voluntary standards"],"lastAction":{"date":"2026-06-25","text":"Ordered to be Reported in the Nature of a Substitute (Amended) by the Yeas and Nays: 29 - 0."}});
  add({"id":"fed-hr-9477","level":"federal","bill":"H.R. 9477","title":"AI Incident Reporting Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/9477/text"},"status":"Introduced June 25, 2026. Committee: Energy and Commerce","summary":"Would require developers of covered models to report AI security incidents, such as attempts to evade oversight.","topics":["Catastrophic risk","Transparency"],"lastAction":{"date":"2026-06-25","text":"Referred to the House Committee on Energy and Commerce."}});
  add({"id":"fed-s-5061","level":"federal","bill":"S. 5061","title":"Secure A.I. Development Act of 2026","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/senate-bill/5061/text"},"status":"Introduced July 21, 2026. Committee: Commerce, Science, and Transportation","summary":"Would require frontier models to go to the NSA for testing 21 days before release, create an AI risk board at NIST, and set up voluntary incident reporting with a public database.","topics":["Catastrophic risk","Mandatory testing","Transparency"],"lastAction":{"date":"2026-07-21","text":"Read twice and referred to the Committee on Commerce, Science, and Transportation."}});
  add({"id":"fed-hr-9925","level":"federal","bill":"H.R. 9925","title":"FRONTIER Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/9925/text"},"status":"Introduced July 23, 2026. Committee: Science, Space, and Technology; Energy and Commerce","summary":"Would make large developers publish frontier-AI safety frameworks and submit to licensed independent audits under new Commerce rules, with emergency power to suspend a model, incident reporting and registration.","topics":["Catastrophic risk","Third-party audits","Shutdown or kill switch","Transparency"],"lastAction":{"date":"2026-07-23","text":"Referred to the Committee on Energy and Commerce, and in addition to the Committee on Science, Space, and Technology, for a period to be subsequently determined by the Speaker, in each case for consideration of such provisions as fall within the jurisdiction of the committee concerned."}});
  add({"id":"fed-hr-9917","level":"federal","bill":"H.R. 9917","title":"AI Kill Switch Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/9917/text"},"status":"Introduced July 23, 2026. Committee: Homeland Security","summary":"Would require select AI developers to be able to restrict or shut down their systems, and let DHS order it after a covered incident such as loss of control.","topics":["Catastrophic risk","Shutdown or kill switch"],"lastAction":{"date":"2026-07-24","text":"Referred to the Subcommittee on Cybersecurity and Infrastructure Protection."}});
  add({"id":"fed-hr-9914","level":"federal","bill":"H.R. 9914; S. 5105","title":"Collaboration on Adversarial Threats and Security Risks Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/9914/text"},"status":"Introduced in the House July 23, 2026 and in the Senate July 23, 2026. Committees: House: Judiciary. Senate: Judiciary","summary":"Would grant an antitrust exemption for sharing information or agreeing to pause or limit AI work to reduce risks such as weapons development, infrastructure interference or loss of control.","topics":["Catastrophic risk","Deregulation"],"lastAction":{"date":"2026-07-23","text":"Referred to the House Committee on the Judiciary."}});
  add({"id":"fed-hr-9965","level":"federal","bill":"H.R. 9965","title":"AI Threat Output and Monitoring Incident Containment Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/9965/text"},"status":"Introduced July 27, 2026. Committee: Science, Space, and Technology","summary":"Would start a program, which large developers must join, assessing whether AI models could help build a nuclear weapon or slip out of control, with recommendations to Congress.","topics":["Catastrophic risk","Mandatory testing"],"lastAction":{"date":"2026-07-27","text":"Referred to the House Committee on Science, Space, and Technology."}});
  add({"id":"fed-hr-10362","level":"federal","bill":"H.R. 10362","title":"Stop Rogue AI Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/10362/text"},"status":"Introduced September 14, 2026. Committee: Oversight and Government Reform; Science, Space, and Technology","summary":"Would have NIST and Commerce develop standards for AI agents and make following them a condition of federal procurement.","topics":["Catastrophic risk","Voluntary standards"],"lastAction":{"date":"2026-09-14","text":"Referred to the Committee on Science, Space, and Technology, and in addition to the Committee on Oversight and Government Reform, for a period to be subsequently determined by the Speaker, in each case for consideration of such provisions as fall within the jurisdiction of the committee concerned."}});
  add({"id":"fed-s-5417","level":"federal","bill":"S. 5417; H.R. 10567","title":"AI Emergency Button Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/senate-bill/5417/text"},"status":"Introduced in the Senate September 16, 2026 and in the House September 24, 2026. Committees: Senate: Commerce, Science, and Transportation. House: Science, Space, and Technology","summary":"Would require AI developers and operators to keep a way for a human to shut down their systems.","topics":["Catastrophic risk","Shutdown or kill switch"],"lastAction":{"date":"2026-09-24","text":"Referred to the House Committee on Science, Space, and Technology."}});
  add({"id":"fed-s-5493","level":"federal","bill":"S. 5493; H.R. 10538","title":"Ban Artificial Superintelligence Act of 2026","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/senate-bill/5493/text"},"status":"Introduced in the Senate September 23, 2026 and in the House September 24, 2026. Committees: Senate: Commerce, Science, and Transportation. House: Oversight and Government Reform","summary":"Would create a Department of Artificial Intelligence, pause advanced AI development until it is staffed and has issued rules, and ban AI with certain “superintelligence precursor” traits.","topics":["Catastrophic risk","Restricting AI development","Transparency"],"lastAction":{"date":"2026-09-24","text":"Referred to the House Committee on Oversight and Government Reform."}});
