  const S = (state, bill, session, stage, date, text, title, summary, subjects, url, official, passing) => {
    const b = { id: 'os-' + state.toLowerCase() + '-' + session + '-' + bill.toLowerCase().replace(/[^a-z0-9]+/g, '-'), level: 'state', state, bill, session: SESSIONS[session], stage,
      source: url ? { label: official ? 'Legislature' : 'Open States', url } : OS };
    if (title) b.title = title; if (summary) b.summary = summary; if (date) b.lastAction = text ? { date, text } : { date };
    if (subjects.length) b.subjects = subjects.map(i => SUBJECTS[i]);
    if (passing) b.passing = true;
    add(b);
  };
